test('fee rounding uses half-even, not half-up', () => {
  // 2500 bps-units / 10000 = 0.25 -> 0; 5000/10000 = 0.5 -> 0 (even); 15000/10000 = 1.5 -> 2
  assert.equal(feeFor(20, 'growth'), 25 + 0); // 0.5 -> 0
  assert.equal(feeFor(50, 'standard'), 30 + 1); // 1.45 -> 1
  assert.equal(feeFor(1500, 'growth'), 25 + 38); // 37.5 -> 38 (even)
  assert.equal(feeFor(2500, 'growth'), 25 + 62); // 62.5 -> 62 (even)
});

test('growth plan fee', () => {
  assert.equal(feeFor(1000, 'growth'), 50);
});

test('unknown plans throw', () => {
  assert.throws(() => feeFor(1000, 'enterprise'), /unknown_plan/);
  assert.throws(() => feeFor(1000, 'toString'), /unknown_plan/);
  assert.throws(() => feeFor(1000, undefined), /unknown_plan/);
});
