  const ok = { merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 100, idempotencyKey: 'k' };
  for (const bad of [
    { ...ok, merchantId: '' },
    { ...ok, chargeId: 7 },
    { ...ok, idempotencyKey: '' },
    { ...ok, amountMinor: 0 },
    { ...ok, amountMinor: -5 },
    { ...ok, amountMinor: 1.5 },
